import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.DajbkT6K.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),r={name:"en/guide/faq.md"};function s(i,e,h,l,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Whenever something goes wrong, the first step is always to <strong>tell your persona what&#39;s happening</strong>: the exact error, what you did, and what you expected. It can see a lot that you can&#39;t, and it can usually figure out most problems on its own.</p><h2 id="installing-and-launching" tabindex="-1">Installing and launching <a class="header-anchor" href="#installing-and-launching" aria-label="Permalink to &quot;Installing and launching&quot;">​</a></h2><p><strong>Mac says &quot;cannot verify the developer&quot; or &quot;is damaged and can&#39;t be opened&quot;</strong> The installer isn&#39;t signed with a paid Apple developer certificate. Open <strong>Terminal</strong>, run the line below, and open it again:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/全能管家.app</span></span></code></pre></div><p><strong>Windows says &quot;Windows protected your PC&quot;</strong> Click <strong>More info</strong> → <strong>Run anyway</strong>.</p><h2 id="the-persona-won-t-talk" tabindex="-1">The persona won&#39;t talk <a class="header-anchor" href="#the-persona-won-t-talk" aria-label="Permalink to &quot;The persona won&#39;t talk&quot;">​</a></h2><p><strong>&quot;has no model selected and cannot reply&quot;</strong> Go to <strong>Personas</strong> → that persona → the <strong>AI</strong> tab and pick a model.</p><p><strong>Getting a 401 error, or &quot;bad key&quot;</strong> Go to System Settings → <strong>Model providers</strong> → <strong>API credentials</strong>, and click <strong>Test</strong> on that entry. If it fails, re-copy and paste the key, watching for extra spaces at either end. If you&#39;re on a subscription, check whether <strong>Claude subscription</strong> still shows <strong>On and logged in</strong>.</p><p><strong>Getting a 400 error, on and off</strong> Usually the gateway or provider is temporarily rejecting requests — try again shortly. If it keeps happening, switch to a different route, or send the raw error to your persona.</p><p><strong>Changed a setting and it didn&#39;t take effect</strong> For access method, model, or search settings, reopen that persona after making the change.</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p><strong>It doesn&#39;t remember what we just said</strong> When a conversation runs long, the persona reorganizes its context and starts a fresh thread — the raw chat text doesn&#39;t all carry over, but anything important has already been saved to memory. To make sure something sticks, say &quot;Remember: …&quot; explicitly.</p><p><strong>It remembers something wrong</strong> Just correct it directly: &quot;No, it should be…&quot;. It will overwrite the old memory.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p><strong>The bot isn&#39;t receiving messages</strong> Make sure the persona is running, and check that the card shows <strong>Running</strong>. If you changed permissions or events in Feishu or DingTalk, you need to publish a new version; for Discord, make sure <strong>Message Content Intent</strong> is turned on. See <a href="/aibutler/docs/en/guide/channels.html">Channels</a> for details.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p><strong>Can&#39;t find anything</strong> See <a href="/aibutler/docs/en/guide/search.html">Web Search</a>. In mainland China, adding Bing usually solves it.</p><h2 id="where-s-the-data" tabindex="-1">Where&#39;s the data <a class="header-anchor" href="#where-s-the-data" aria-label="Permalink to &quot;Where&#39;s the data&quot;">​</a></h2><p>All data lives on your own computer. On Mac it defaults to <code>~/Library/Application Support/butler</code>, on Windows to <code>%APPDATA%\\butler</code>. Each persona&#39;s files are in the folder you chose when creating it.</p>',20)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
